tes", "valor": "3,18", "unidade": "", "situacao": "atencao", "tendencia": "estavel"}, {"nome": "Ocorrências por Entrega", "valor": "0,42", "unidade": "", "situacao": "atencao", "tendencia": "estavel"}], "planoDeAcao": [{"prazo": "30 dias", "titulo": "Mapeamento e Replanejamento de Rotas Críticas", "descricao": "Analisar rotas das regiões Norte e Centro-Oeste com alta taxa de atraso e custo de combustível, aplicando algoritmo de roteirização.", "prioridade": "alta", "resultadoEsperado": "Redução da taxa de atraso em 10% e economia de combustível de 5%."}, {"prazo": "45 dias", "titulo": "Negociação com Distribuidoras de Combustível", "descricao": "Abrir cotação com três fornecedores e fechar contrato com melhor preço e condições de pagamento.", "prioridade": "media", "resultadoEsperado": "Redução do custo médio de combustível para aproximadamente R$ 2.000 por entrega."}, {"prazo": "60 dias", "titulo": "Implementação de Programa de Manutenção Preventiva", "descricao": "Criar calendário de inspeções mensais e substituir veículos com consumo acima de R$ 3.000.", "prioridade": "alta", "resultadoEsperado": "Diminuição de ocorrências em 20% e redução do consumo de combustível em 12%."}, {"prazo": "20 dias", "titulo": "Treinamento de Motoristas em Condução Econômica", "descricao": "Realizar workshop de 8 horas para todos os motoristas, focando em aceleração suave e uso de rotas otimizadas.", "prioridade": "media", "resultadoEsperado": "Melhoria de 5% na taxa de atraso e redução de 3% no consumo de combustível."}, {"prazo": "90 dias", "titulo": "Adoção de Sistema de Balanceamento de Carga", "descricao": "Integrar software que distribua peso e volume de forma equilibrada entre veículos.", "prioridade": "baixa", "resultadoEsperado": "Redução de danos ao veículo e menor necessidade de manutenção corretiva."}, {"prazo": "40 dias", "titulo": "Campanha de Melhoria da Experiência do Cliente", "descricao": "Coletar feedback detalhado pós‑entrega e implementar ações corretivas nas áre